		type ipv4_addr
		comment "default network IPs of pods in user defined networks (IPv4)"
	}

	set udn-pod-default-ips-v6 {
		type ipv6_addr
		comment "default network IPs of pods in user defined networks (IPv6)"
	}

	set mgmtport-no-snat-nodeports {
		type inet_proto . inet_service
		comment "NodePorts not subject to management port SNAT"
	}

	set mgmtport-no-snat-services-v4 {
		type ipv4_addr . inet_proto . inet_service
		comment "eTP:Local short-circuit not subject to management port SNAT (IPv4)"
	}

	set mgmtport-no-snat-services-v6 {
		type ipv6_addr . inet_proto . inet_service
		comment "eTP:Local short-circuit not subject to management port SNAT (IPv6)"
	}

	set mgmtport-no-snat-subnets-v4 {
		type ipv4_addr
		flags interval
		comment "subnets not subject to management port SNAT (IPv4)"
	}

	set mgmtport-no-snat-subnets-v6 {
		type ipv6_addr
		flags interval
		comment "subnets not subject to management port SNAT (IPv6)"
	}

	map external-ips-etp-local-v4 {
		type ipv4_addr . inet_proto . inet_service : ipv4_addr . inet_service
		comment "DNAT mappings for IPv4 ExternalIP/LB traffic with ExternalTrafficPolicy: Local"
	}

	map external-ips-etp-local-v6 {
		type ipv6_addr . inet_proto . inet_service : ipv6_addr . inet_service
		comment "DNAT mappings for IPv6 ExternalIP/LB traffic with ExternalTrafficPolicy: Local"
	}

	map nodeports-etp-local-v4 {
		type inet_proto . inet_service : ipv4_addr . inet_service
		comment "DNAT mappings for IPv4 NodePort traffic with ExternalTrafficPolicy: Local"
	}

	map nodeports-etp-local-v6 {
		type inet_proto . inet_service : ipv6_addr . inet_service
		comment "DNAT mappings for IPv6 NodePort traffic with ExternalTrafficPolicy: Local"
	}

	map external-ips-v4 {
		type ipv4_addr . inet_proto . inet_service : ipv4_addr . inet_service
		comment "DNAT mappings for ordinary IPv4 ExternalIP/LB traffic"
	}

	map external-ips-v6 {
		type ipv6_addr . inet_proto . inet_service : ipv6_addr . inet_service
		comment "DNAT mappings for ordinary IPv6 ExternalIP/LB traffic"
	}

	map nodeports-v4 {
		type inet_proto . inet_service : ipv4_addr . inet_service
		comment "DNAT mappings for ordinary IPv4 NodePort traffic"
	}

	map nodeports-v6 {
		type inet_proto . inet_service : ipv6_addr . inet_service
		comment "DNAT mappings for ordinary IPv6 NodePort traffic"
	}

	set itp-services-to-mark-v4 {
		type ipv4_addr . inet_proto . inet_service
		comment "InternalTrafficPolicy: Local traffic to mark for special routing"
	}

	set itp-services-to-mark-v6 {
		type ipv6_addr . inet_proto . inet_service
		comment "InternalTrafficPolicy: Local traffic to mark for special routing"
	}

	map itp-services-to-redirect-v4 {
		type ipv4_addr . inet_proto . inet_service : inet_service
		comment "Port redirections for ordinary InternalTrafficPolicy: Local traffic"
	}

	map itp-services-to-redirect-v6 {
		type ipv6_addr . inet_proto . inet_service : inet_service
		comment "Port redirections for ordinary InternalTrafficPolicy: Local traffic"
	}

	map udn-mark-nodeports {
		type inet_proto . inet_service : verdict
		comment "UDN services NodePorts mark"
	}

	map udn-mark-external-ips-v4 {
		type ipv4_addr . inet_proto . inet_service : verdict
		comment "UDN services External IPs mark (IPv4)"
	}

	map udn-mark-external-ips-v6 {
		type ipv6_addr . inet_proto . inet_service : verdict
		comment "UDN services External IPs mark (IPv6)"
	}

	map egress-service-snat-v4 {
		type ipv4_addr : ipv4_addr
	}

	map egress-ip-snat-v4 {
		type ipv4_addr . ifname : ipv4_addr
	}

	chain no-pmtud {
		comment "Block egress needs frag/packet too big to remote k8s nodes"
		type filter hook output priority filter; policy accept;
		ip daddr @remote-node-ips-v4 icmp type destination-unreachable icmp code 4 drop
	}

	chain udn-isolation {
		comment "Host isolation for user defined networks"
		type filter hook output priority filter; policy accept;
		ip daddr . meta l4proto . th dport @udn-open-ports-v4 accept
		ip daddr @udn-open-ports-icmp-v4 meta l4proto icmp accept
		socket cgroupv2 level 2 "system.slice/kubelet.service" ip daddr @udn-pod-default-ips-v4 accept
		ip daddr @udn-pod-default-ips-v4 drop
	}

	chain mcs-blocking {
		tcp dport { 22623, 22624 } tcp flags & (fin | syn | rst | ack) == syn reject
	}

	chain mcs-blocking-output {
		type filter hook output priority filter; policy accept;
		jump mcs-blocking
	}

	chain mcs-blocking-forward {
		type filter hook forward priority filter; policy accept;
		jump mcs-blocking
	}

	chain services {
		comment "DNAT for ordinary NodePort/ExternalIP/LB traffic"
		dnat ip to ip daddr . meta l4proto . th dport map @external-ips-v4
		dnat ip6 to ip6 daddr . meta l4proto . th dport map @external-ips-v6
		fib daddr type local dnat ip to meta l4proto . th dport map @nodeports-v4
		fib daddr type local dnat ip6 to meta l4proto . th dport map @nodeports-v6
	}

	chain services-etp {
		comment "Special DNAT for NodePort/ExternalIP/LB traffic with ExternalTrafficPolicy: Local"
		dnat ip to ip daddr . meta l4proto . th dport map @external-ips-etp-local-v4
		dnat ip6 to ip6 daddr . meta l4proto . th dport map @external-ips-etp-local-v6
		fib daddr type local dnat ip to meta l4proto . th dport map @nodeports-etp-local-v4
		fib daddr type local dnat ip6 to meta l4proto . th dport map @nodeports-etp-local-v6
	}

	chain services-etp-no-nodeport {
		comment "Special DNAT for ExternalIP/LB traffic with ExternalTrafficPolicy: Local and no NodePorts"
	}

	chain services-itp {
		comment "Redirects for traffic with InternalTrafficPolicy: Local"
		meta l4proto { tcp, udp, sctp } redirect to :ip daddr . meta l4proto . th dport map @itp-services-to-redirect-v4
		meta l4proto { tcp, udp, sctp } redirect to :ip6 daddr . meta l4proto . th dport map @itp-services-to-redirect-v6
	}

	chain services-prerouting {
		type nat hook prerouting priority dstnat; policy accept;
		jump services-etp
		jump services-etp-no-nodeport
		jump services
	}

	chain services-output {
		type nat hook output priority dstnat; policy accept;
		jump services-itp
		jump services
	}

	chain services-itp-mark {
		comment "Chain to mark InternalTrafficPolicy: Local traffic for special routing"
		type route hook output priority mangle; policy accept;
		ip daddr . meta l4proto . th dport @itp-services-to-mark-v4 meta mark set 0x001745ec
		ip6 daddr . meta l4proto . th dport @itp-services-to-mark-v6 meta mark set 0x001745ec
	}

	chain udn-service-mark {
		comment "UDN services packet mark"
		fib daddr type local meta l4proto . th dport vmap @udn-mark-nodeports
		ip daddr . meta l4proto . th dport vmap @udn-mark-external-ips-v4
		ip6 daddr . meta l4proto . th dport vmap @udn-mark-external-ips-v6
	}

	chain udn-service-prerouting {
		comment "UDN services packet mark - Prerouting"
		type filter hook prerouting priority mangle; policy accept;
		iifname != "ovn-k8s-mp0" jump udn-service-mark
	}

	chain udn-service-output {
		comment "UDN services packet mark - Output"
		type filter hook output priority mangle; policy accept;
		jump udn-service-mark
	}

	chain ovn-kube-pod-subnet-masq {
	}

	chain mgmtport-snat {
		comment "OVN SNAT to Management Port"
		type nat hook postrouting priority srcnat; policy accept;
		oifname != "ovn-k8s-mp0" return
		meta l4proto . th dport @mgmtport-no-snat-nodeports return
		ip saddr 10.128.0.2 return
		ip daddr . meta l4proto . th dport @mgmtport-no-snat-services-v4 return
		ip saddr @mgmtport-no-snat-subnets-v4 return
		snat ip to 10.128.0.2
	}

	chain egress-services {
		type nat hook postrouting priority srcnat; policy accept;
		meta mark 0x000003f0 return comment "DoNotSNAT"
		snat ip to ip saddr map @egress-service-snat-v4
	}

	chain egress-ip-snat {
		type nat hook postrouting priority srcnat; policy accept;
		snat ip to ip saddr . oifname map @egress-ip-snat-v4
	}

	chain egress-ip-sec-filter {
		comment "Egress IP on secondary interfaces filtering"
		type filter hook postrouting priority srcnat + 1; policy accept;
		ip saddr 10.128.0.0/14 meta mark 0x000003f1 drop comment "Drop egress IP pod traffic from 10.128.0.0/14"
	}
}

